  static object Call(string name,params object[] args){try{return Api.GetMethods(BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic).Single(m=>m.Name==name&&m.GetParameters().Length==args.Length).Invoke(null,args);}catch(TargetInvocationException x){throw x.InnerException;}}
