  }
  public static int Main(){try{Run();Console.WriteLine("SAVE DELETION PASSED: "+checks+" assertions");return 0;}catch(Exception x){Console.WriteLine(x);return 1;}}
  public static void Run(){
   // Break caught: absent service, unchecked folder resolution, or deletion before explicit confirmation.
   Api=typeof(Engine).Assembly.GetType("PZ3D.SaveDeletion");Check(Api!=null,"guarded save recycling API exists");
