   foreach(string id in new[]{"../OnlyThis","Survivor/../OnlyThis","Survivor/OnlyThis/map","Survivor\\OnlyThis","Survivor/OnlyThis.",new string('x',261)})Refuses(()=>Call("Preview",f.E,id),"traversal, nesting or oversized ID refused: "+id.Substring(0,Math.Min(id.Length,40)));
   Guards();MutexWriter();TokenCancellation();Reparse(false);Reparse(true);SnapshotEdges();NativeSink();
  }
  static void TokenCancellation(){
   // Break caught: Cancel arrives during mutex wait but deletion still reaches the recycler.
   Check(Api.GetMethods(BindingFlags.Static|BindingFlags.NonPublic).Any(m=>m.Name=="Delete"&&m.GetParameters().Length==7),"service accepts cancellation through final guarded boundary");var f=new Fixture();string stamp=f.Stamp(),name="Local\\OrangeSaveProfiles-"+DlssInstaller.Hash(Encoding.UTF8.GetBytes(System.IO.Path.GetFullPath(System.IO.Path.Combine(f.Path,"mods.txt")).ToUpperInvariant())).ToLowerInvariant();Exception error=null;
   using(var cancel=new CancellationTokenSource())using(var entered=new ManualResetEventSlim())using(var mutex=new Mutex(false,name)){mutex.WaitOne();var deleting=new Thread(()=>{try{Call("Delete",f.E,f.Id,stamp,true,new Action<string>(f.Move),new Func<bool>(()=>{entered.Set();return false;}),cancel.Token);}catch(Exception x){error=x;}});try{deleting.Start();Check(entered.Wait(5000),"deletion begins while writer owns per-save mutex");cancel.Cancel();}finally{mutex.ReleaseMutex();}deleting.Join();Check(error is OperationCanceledException&&File.ReadAllText(f.Marker)=="original marker bytes","cancellation during mutex wait prevents recycle and keeps marker bytes");}
  }
  static void SnapshotEdges(){
   // Break caught: root replacement, newly introduced junctions, or empty directory changes reuse consent.
   var f=new Fixture();string stamp=f.Stamp();string moved=f.Path+"-previous";Directory.Move(f.Path,moved);Directory.CreateDirectory(f.Path);Put(f.Marker,"original marker bytes");foreach(string relative in new[]{"map/marker.bin","map",""}){string old=System.IO.Path.Combine(moved,relative),current=System.IO.Path.Combine(f.Path,relative);if(File.Exists(old)){File.SetCreationTimeUtc(current,File.GetCreationTimeUtc(old));File.SetLastWriteTimeUtc(current,File.GetLastWriteTimeUtc(old));}else{Directory.SetCreationTimeUtc(current,Directory.GetCreationTimeUtc(old));Directory.SetLastWriteTimeUtc(current,Directory.GetLastWriteTimeUtc(old));}}Check(File.GetLastWriteTimeUtc(f.Marker)==File.GetLastWriteTimeUtc(System.IO.Path.Combine(moved,"map/marker.bin"))&&Directory.GetCreationTimeUtc(f.Path)==Directory.GetCreationTimeUtc(moved),"replacement fixture preserves metadata independently of file identity");Refuses(()=>f.Delete(stamp,true,f.Move),"replaced target directory cannot reuse preview even with matching metadata");
   stamp=f.Stamp();Directory.CreateDirectory(System.IO.Path.Combine(f.Path,"empty"));Refuses(()=>f.Delete(stamp,true,f.Move),"new empty directory invalidates preview");stamp=f.Stamp();Junction(System.IO.Path.Combine(f.Path,"newlink"),moved);Refuses(()=>f.Delete(stamp,true,f.Move),"junction added after preview refuses before recycle");Check(File.Exists(f.Marker),"stale and reparse refusals preserve source");
   var root=new Fixture();string saves=System.IO.Path.Combine(root.E.User,"Saves"),foreign=System.IO.Path.Combine(root.Root,"MovedSaves");Directory.Move(saves,foreign);Junction(saves,foreign);Refuses(()=>Call("Preview",root.E,root.Id),"Saves root junction refuses without descending");
